package com.golem.boxy.seedlod;

import com.golem.boxy.seedlod.share.SharingServer;
import com.golem.boxy.vss.config.VSSServerConfig;
import com.golem.boxy.vss.net.VssChannels;
import com.golem.boxy.vss.payloads.SeedRequestC2SPayload;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.fml.loading.FMLEnvironment;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Seed LODs: Voxy terrain drawn from the world seed where Boxy has no real terrain yet, generated by vanilla's
 * own worldgen code (density functions, surface rules, features and structures) run against single columns.
 * Common entry point; the server only answers seed requests, and only with {@code shareSeedWithClients} on.
 */
public final class SeedLods {
   public static final Logger LOGGER = LoggerFactory.getLogger("Boxy SeedLODs");

   private SeedLods() {
   }

   public static void init() {
      VssChannels.seedServerHandler = new VssChannels.SeedHandler() {
         @Override
         public void onSeedRequest(ServerPlayer sender, SeedRequestC2SPayload payload) {
            SharingServer.onRequest(sender, payload);
         }
      };
      if (FMLEnvironment.dist.isDedicatedServer()) {
         LOGGER.info("Seed sharing with Boxy clients is {}", VSSServerConfig.CONFIG.shareSeedWithClients ? "on" : "off (shareSeedWithClients)");
      }
   }
}
